"""Storage interface for uploaded and generated files.

Paths are always generated by the app (never taken from user input), e.g.
`resumes/<profile id>/<uuid>.pdf`. Backends must still refuse paths that
could escape their root.
"""

import re
from dataclasses import dataclass
from datetime import datetime
from typing import Protocol

from fastapi import status

from app.core.exceptions import AppError

_SAFE_PATH = re.compile(r"^[A-Za-z0-9_-]+(/[A-Za-z0-9_.-]+)*$")


class StorageError(AppError):
    status_code = status.HTTP_503_SERVICE_UNAVAILABLE
    code = "storage_unavailable"


class StorageNotFoundError(AppError):
    status_code = status.HTTP_404_NOT_FOUND
    code = "not_found"


def check_path(path: str) -> str:
    if not _SAFE_PATH.match(path) or ".." in path.split("/"):
        raise ValueError(f"unsafe storage path: {path!r}")
    return path


@dataclass(frozen=True)
class StoredFile:
    path: str
    size: int
    modified: datetime | None  # None when the backend does not say


class StorageBackend(Protocol):
    name: str

    async def put(self, path: str, data: bytes, content_type: str) -> None: ...

    async def get(self, path: str) -> bytes: ...

    async def delete(self, path: str) -> None:
        """Delete; a missing object is not an error."""
        ...

    async def list_files(self, prefix: str) -> list[StoredFile]:
        """Every file under `prefix` (a top-level folder such as "generated")."""
        ...
